#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 3A step 4: ML-KEM-768 KeyGen sequencer
#
# The first point in the project where the whole ML-KEM key generation runs as
# one machine: sponge, both samplers, NTT, basemul, codec and both memories,
# each verified standalone before being connected here.
#
# Verified against four ACVP-traceable vectors, ek (1184 bytes) and dk (2400
# bytes) compared byte for byte, plus five intermediate polynomial checkpoints
# that isolate each pipeline stage.
#
# Nine defects were found during bring-up; they are written up in
# doc/L3A_KEYGEN.md. Six were variations of one mistake: treating a
# synchronous interface as if it responded combinationally.
#
# NOTE ON byte_mem.vhd: this script REPLACES it. Addresses widened from 12 to
# 13 bits because dk ends at byte 4192, past the 12-bit limit. The codec
# coefficients stay 12 bits, since a Kyber coefficient needs 12 (q < 4096).
# tb_codec12 is updated to match and is re-run below to prove its signature is
# unchanged.
#
# Requires all earlier Layer 3A deliveries.
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected final line: PQC L3A KEYGEN PASS vectors=4 sig=c268044aef8e69c0
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif" "$DEST/doc"
  for f in rtl/poly_mem.vhd rtl/basemul_k.vhd rtl/keccak_sponge.vhd \
           rtl/sampler_ntt_k.vhd rtl/sampler_misc.vhd rtl/ntt_unit.vhd; do
    if [ ! -f "$DEST/$f" ]; then
      echo "MISSING PREREQUISITE: $f"
      exit 1
    fi
  done
  base64 -d > "$DEST/rtl/kem_keygen.vhd" << 'B64EOF'
LS0gPT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09PT09
PT09PT09PT09PT09PT09PT09PT09PT0KLS0gSEVSQ09TU05VWCBQUUMgSVAgQ29yZSAtIExheWVy
IDNBCi0tIGtlbV9rZXlnZW46IE1MLUtFTS03NjggS2V5R2VuIHNlcXVlbmNlciwgRklQUyAyMDMg
QWxnb3JpdGhtcyAxMyBhbmQgMTYuCi0tIFZIREwtMjAwOC4gQVNDSUktb25seS4gTUlUIGxpY2Vu
c2UuCi0tCi0tIE9yY2hlc3RyYXRlcyB0aGUgdmVyaWZpZWQgYmxvY2tzIG92ZXIgdGhlIHNoYXJl
ZCBtZW1vcmllczoKLS0gICBzcG9uZ2UgKFNIQTMtNTEyLCBTSEEzLTI1NiwgU0hBS0UyNTYsIFNI
QUtFMTI4KQotLSAgIHNhbXBsZXJfbnR0X2sgKFNhbXBsZU5UVCksIHNhbXBsZXJfY2JkX2sgKFNh
