B64EOF
  chmod +x "$DEST/verif/mutate_kg.sh"
  cd "$DEST/verif"
  rm -rf work-obj08.cf
  ghdl -a --std=08 ../rtl/keccak_pkg.vhd ../rtl/keccak_f1600.vhd \
       ../rtl/keccak_sponge.vhd ../rtl/ntt_tables_pkg.vhd ../rtl/ntt_unit.vhd \
       ../rtl/sampler_ntt_k.vhd ../rtl/sampler_misc.vhd ../rtl/basemul_k.vhd \
       ../rtl/poly_mem.vhd ../rtl/byte_mem.vhd ../rtl/kem_keygen.vhd \
       ../rtl/kem_keygen_top.vhd \
       tb_poly_mem.vhd tb_datapath.vhd tb_codec12.vhd tb_keygen.vhd \
       tb_checkpoint.vhd

  echo "--- regression: previously verified blocks ---"
  for TB in tb_poly_mem tb_datapath tb_codec12; do
    ghdl -e --std=08 $TB > /dev/null 2>&1
  done
  ghdl -r --std=08 tb_poly_mem --stop-time=50ms 2>&1 \
    | grep "POLYMEM PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_datapath --stop-time=300ms 2>&1 \
    | grep "DATAPATH PASS" | sed 's/.*(report note): //'
  ghdl -r --std=08 tb_codec12 --stop-time=200ms 2>&1 \
    | grep "CODEC12 PASS" | sed 's/.*(report note): //'

  echo "--- checkpoints: one polynomial per pipeline stage ---"
  ghdl -e --std=08 tb_checkpoint > /dev/null 2>&1
  for ST in 1 2 3 4 5; do
    ghdl -r --std=08 tb_checkpoint -gG_STAGE=$ST --stop-time=800ms 2>&1 \
      | grep "CHECKPOINT PASS" | sed 's/.*(report note): //'
  done

  echo "--- full KeyGen against ACVP ---"
  ghdl -e --std=08 tb_keygen > /dev/null 2>&1
  ghdl -r --std=08 tb_keygen --stop-time=4000ms 2>&1 \
    | grep "KEYGEN PASS" | sed 's/.*(report note): //'
)
